<?php
namespace App\Exports;
use Illuminate\Support\Collection;use Maatwebsite\Excel\Concerns\FromCollection;use Maatwebsite\Excel\Concerns\ShouldAutoSize;use Maatwebsite\Excel\Concerns\WithHeadings;use Maatwebsite\Excel\Concerns\WithStyles;use Maatwebsite\Excel\Concerns\WithTitle;use PhpOffice\PhpSpreadsheet\Worksheet\Worksheet;
class ChequeReportExport implements FromCollection,WithHeadings,ShouldAutoSize,WithStyles,WithTitle { public function __construct(private Collection$rows){} public function collection(){return$this->rows->map(fn($c)=>[$c->cheque_reference,$c->cheque_type,$c->cheque_number,$c->cheque_date->format('Y-m-d'),$c->customer?->name??$c->supplier?->name??$c->payee_name,$c->bank_name,(float)$c->amount,(float)$c->hold_amount,$c->display_status]);} public function headings():array{return['Reference','Type','Cheque Number','Cheque Date','Party','Bank','Amount','Hold','Status'];} public function styles(Worksheet$sheet){$sheet->freezePane('A2');$sheet->getStyle('A1:I1')->getFont()->setBold(true)->getColor()->setARGB('FFFFFFFF');$sheet->getStyle('A1:I1')->getFill()->setFillType('solid')->getStartColor()->setARGB('FF2563EB');$sheet->getStyle('G2:H'.($this->rows->count()+1))->getNumberFormat()->setFormatCode('#,##0.00');return[];} public function title():string{return'Cheque Report';} }
